	@Test
	void roundTripsUnsignedIdsAndAnOffsetSliceWithoutRetainingTheInput() {
		long[] neighbors = { 99, 2, 2, Long.MAX_VALUE, Long.MIN_VALUE, Long.MIN_VALUE, -2, 99 };
		long[] contexts = { 99, 0, -2, 4, 0, -1, 0, 99 };
		byte[] encoded = PersistentCsfPageCodec.encode(Long.MIN_VALUE, neighbors, contexts, 1, 6);
		PersistentCsfPageCodec.DecodedPage decoded = PersistentCsfPageCodec.decode(ByteBuffer.wrap(encoded));
		Arrays.fill(encoded, (byte) 0);
		assertThat(decoded.rowId()).isEqualTo(Long.MIN_VALUE);
		assertThat(decoded.size()).isEqualTo(6);
		assertThat(decoded.neighbors()).containsExactly(Arrays.copyOfRange(neighbors, 1, 7));
		assertThat(decoded.contexts()).containsExactly(Arrays.copyOfRange(contexts, 1, 7));
		assertThat(decoded.neighborAt(5)).isEqualTo(-2);
		assertThat(decoded.contextAt(4)).isEqualTo(-1);
	}

	@Test
	void payloadIsTheExistingCompactCsfEncodingByteForByte() {
		long[] neighbors = { 9, 9, 10, 11, 11, 11 };
		long[] contexts = { 0, 100, 0, 1, 100, 200 };
		CsfPageData data = new CsfPageData();
		data.beginRow(17);
		for (int i = 0; i < neighbors.length; i++) {
			data.appendPair(neighbors[i], contexts[i], i == 0 || neighbors[i] != neighbors[i - 1]);
		}
		data.endRow();
		CompactCsfPageEncoder.PageImage existing = new CompactCsfPageEncoder().tryEncode(data, false, 0);
		byte[] encoded = PersistentCsfPageCodec.encode(17, neighbors, contexts, 0, neighbors.length);
		assertThat(Arrays.copyOfRange(encoded, PersistentCsfPageCodec.HEADER_BYTES, encoded.length))
				.containsExactly(existing.bytes());
	}

	@Test
	void maximumPageSpansPackedBlocksAndSupportsOneLargeContextFiber() {
		long[] neighbors = new long[PersistentCsfPageCodec.MAX_PAIRS];
		long[] contexts = new long[neighbors.length];
		for (int i = 0; i < neighbors.length; i++) {
			neighbors[i] = i / 3;
			contexts[i] = i % 3;
		}
		assertRoundTrip(neighbors, contexts);
		Arrays.fill(neighbors, 123);
		for (int i = 0; i < contexts.length; i++) {
			contexts[i] = i < 512 ? i : Long.MIN_VALUE + i;
		}
		assertRoundTrip(neighbors, contexts);
	}

	@Test
	void packsMultipleRowsWithIndependentNeighborAndContextRunsUsingTheExistingEncoding() {
		long[] rows = { 1, 1, 1, 2, 2, Long.MIN_VALUE, Long.MIN_VALUE };
		long[] neighbors = { 9, 9, 10, 3, 8, 2, 2 };
		long[] contexts = { 0, 4, 0, 0, -2, 0, 1 };
		byte[] encoded = PersistentCsfPageCodec.encode(rows, neighbors, contexts, 0, rows.length);
		PersistentCsfPageCodec.DecodedPage decoded = PersistentCsfPageCodec.decode(ByteBuffer.wrap(encoded));
		assertThat(decoded.rows()).containsExactly(rows);
		assertThat(decoded.rowId()).isEqualTo(1);
		assertThat(decoded.rowCount()).isEqualTo(3);
		assertThat(decoded.rowAt(5)).isEqualTo(Long.MIN_VALUE);
		assertThat(decoded.neighbors()).containsExactly(neighbors);
		assertThat(decoded.contexts()).containsExactly(contexts);

		CsfPageData existing = new CsfPageData();
		for (int i = 0; i < rows.length; i++) {
			boolean newRow = i == 0 || rows[i] != rows[i - 1];
			if (newRow) {
				if (i > 0) {
					existing.endRow();
				}
				existing.beginRow(rows[i]);
			}
			existing.appendPair(neighbors[i], contexts[i], newRow || neighbors[i] != neighbors[i - 1]);
		}
		existing.endRow();
		assertThat(Arrays.copyOfRange(encoded, PersistentCsfPageCodec.HEADER_BYTES, encoded.length))
				.containsExactly(new CompactCsfPageEncoder().tryEncode(existing, false, 0).bytes());
	}

	@Test
	void packsTheMaximumNumberOfSmallRowsWithoutPerRowPageHeaders() {
		long[] rows = new long[PersistentCsfPageCodec.MAX_PAIRS];
		long[] neighbors = new long[rows.length];
		long[] contexts = new long[rows.length];
		for (int i = 0; i < rows.length; i++) {
			rows[i] = i < 512 ? i : Long.MIN_VALUE + i;
			neighbors[i] = 16L * i + 1;
			contexts[i] = i % 3;
		}
		byte[] encoded = PersistentCsfPageCodec.encode(rows, neighbors, contexts, 0, rows.length);
		PersistentCsfPageCodec.DecodedPage decoded = PersistentCsfPageCodec.decode(ByteBuffer.wrap(encoded));
		assertThat(decoded.rowCount()).isEqualTo(PersistentCsfPageCodec.MAX_PAIRS);
		assertThat(decoded.rows()).containsExactly(rows);
		assertThat(decoded.neighbors()).containsExactly(neighbors);
		assertThat(decoded.contexts()).containsExactly(contexts);
		assertThat(encoded.length).as("small rows share one CSF header and packed vectors").isLessThan(16 * 1024);
	}

	@Test
	void validatesMultirowFiberBoundariesAndQuadCountsWithRecomputedChecksums() {
		for (int field : new int[] { CompactCsfPageFormat.ROW_FIBER_STARTS_OFFSET_AT,
				CompactCsfPageFormat.ROW_QUAD_COUNTS_OFFSET_AT }) {
			byte[] encoded = PersistentCsfPageCodec.encode(new long[] { 1, 1, 1, 2, 2 },
					new long[] { 3, 3, 4, 5, 5 }, new long[] { 0, 1, 0, 0, 1 }, 0, 5);
			ByteBuffer bytes = ByteBuffer.wrap(encoded).order(ByteOrder.LITTLE_ENDIAN);
			int vector = PersistentCsfPageCodec.HEADER_BYTES
					+ bytes.getInt(PersistentCsfPageCodec.HEADER_BYTES + field);
			int firstBlock = vector + bytes.getInt(vector + 8);
			bytes.putLong(firstBlock + 4, Long.MAX_VALUE);
			recomputeChecksum(encoded);
			assertMalformed(encoded);
		}
	}

	@Test
	void decodesReadOnlyDirectSlicesWithoutChangingTheBufferState() {
		byte[] encoded = PersistentCsfPageCodec.encode(7, new long[] { 9 }, new long[] { 0 }, 0, 1);
		ByteBuffer direct = ByteBuffer.allocateDirect(encoded.length + 13).order(ByteOrder.BIG_ENDIAN);
		direct.position(5).put(encoded).flip().position(5);
		ByteBuffer value = direct.asReadOnlyBuffer();
		int position = value.position();
		int limit = value.limit();
		assertThat(PersistentCsfPageCodec.decode(value).neighborAt(0)).isEqualTo(9);
		assertThat(value.position()).isEqualTo(position);
		assertThat(value.limit()).isEqualTo(limit);
		assertThat(value.order()).isEqualTo(ByteOrder.BIG_ENDIAN);
	}

	@Test
	void rejectsEveryTruncationAndTrailingBytes() {
		byte[] encoded = sample();
		for (int length = 0; length < encoded.length; length++) {
			ByteBuffer truncated = ByteBuffer.wrap(encoded, 0, length);
			assertThatThrownBy(() -> PersistentCsfPageCodec.decode(truncated))
					.as("truncated length %s", length)
					.isInstanceOf(IllegalArgumentException.class);
		}
		assertMalformed(Arrays.copyOf(encoded, encoded.length + 1));
	}

