	private static void assertMalformed(byte[] encoded) {
		assertThatThrownBy(() -> PersistentCsfPageCodec.decode(ByteBuffer.wrap(encoded)))
				.isInstanceOf(IllegalArgumentException.class);
	}

	private static void recomputeChecksum(byte[] encoded) {
		CRC32C checksum = new CRC32C();
		checksum.update(encoded, PersistentCsfPageCodec.HEADER_BYTES,
				encoded.length - PersistentCsfPageCodec.HEADER_BYTES);
		ByteBuffer.wrap(encoded)
				.order(ByteOrder.LITTLE_ENDIAN)
				.putInt(PersistentCsfPageCodec.CHECKSUM_AT, (int) checksum.getValue());
	}
